#include <bits/stdc++.h>
using namespace std;

int main() {
	int h,w,ans=0;
	string s;

	cin >> h >> w;
	for(int i=0;i<h;i++){
		cin>>s;
		ans += count(s.begin(), s.end(), '#'); //if文の場合と, この行だけ異なる
	}

	cout << ans <<endl;
	return 0;
}
